def qualifier(text):
 for a,b in sorted(Q.items(),key=lambda x:len(x[0]),reverse=True):text=text.replace(a,b)
 return text.replace('mm',' мм')
def stem(text,context):
 text=text.strip(' -|=')
 if text in BASE:return BASE[text]
 # Containers are named in their set's context, preserving implant/plate/screw distinctions.
 if 'Case'in text:
  kind='винтов'if 'Screw Case'in text else'пластин'if 'Plate Case'in text else'имплантов'if re.search(r'Implants? Case',text)else'инструментов'
  if 'Rods & Nuts'in text:kind='стержней и гаек'
  return 'Контейнер '+kind+' — '+context.removeprefix('Набор инструментов ').removeprefix('Дополнительный набор инструментов ')
 for prefix in ['HOBBIT MIS','TINA MIS','Endo LIF','HOBBIT','TINA','MIS','CT','OCT','ATP','OLIF','PLIF','FC','ACR','4.5/4.75']:
  if text.startswith(prefix+' '):return stem(text[len(prefix)+1:],context)+' '+prefix
 if text.endswith((' I',' II',' III',' IV')):
  root,roman=text.rsplit(' ',1);return stem(root,context)+' '+roman
 if ' for 'in text:
  a,b=text.split(' for ',1)
  if b in DEP:return stem(a,context)+' для '+DEP[b]
 if text.startswith('90 Degree Push Curette'):return 'Толкающая кюретка 90 градусов'
 if text.startswith('45 Degree Pull Curette'):return 'Тянущая кюретка 45 градусов'
 if text.startswith('90 Degree Pull Curette'):return 'Тянущая кюретка 90 градусов'
 for name,value in sorted(BASE.items(),key=lambda x:len(x[0]),reverse=True):
  if text.startswith(name+' '):return value+' '+qualifier(text[len(name)+1:])
 return qualifier(text)
def translate(en,context):
 head,*tail=en.split(',');ru=stem(head,context)
 for suffix in tail:
  suffix=suffix.strip()
  if suffix.startswith('for '):ru+=', для '+DEP.get(suffix[4:],qualifier(suffix[4:]))
  else:ru+=', '+qualifier(suffix)
 ru=ru.replace('Торx','Torx').replace('  ',' ')
 return {'ru':ru,'en':en}
# Source-specific terminology reviewed by Codex for this import.
BASE.update({'Rod Holder':'Держатель стержня','Drill Sleeve':'Сверлильная втулка','Pusher for Lamina Hook':'Толкатель ламинарного крючка'})
DEP.update({'Screw Cutter':'кусачек для винтов','Screw Cutter Set':'набора для обрезки винтов','Long Arm Pedicle Screw':'транспедикулярного винта с удлинёнными лепестками','CT Screw Cutter Set':'набора для обрезки винтов CT','CT Long Arm Screws':'винтов CT с удлинёнными лепестками','Polyaxial Pedicle Screws (llium)':'полиаксиальных транспедикулярных винтов (подвздошная кость)','FC Cage':'кейджа FC','Polyaxial Pedicle Screw':'полиаксиального транспедикулярного винта','Monoaxial Pedicle Screw':'моноаксиального транспедикулярного винта','Cancellous Bone Graft':'губчатого костного трансплантата','cage':'кейджа','Scalpel':'скальпеля','Packing Block':'блока для заполнения костным материалом','Mesh':'сетки','Distractor':'дистрактора','vertebral body':'тела позвонка','Two-step Outer Nut':'двухступенчатой наружной гайки','inserting screws':'введения винтов','inserting Screws':'введения винтов','extracting Screws':'извлечения винтов','retaining screw':'удерживающего винта','final tightening':'окончательного затягивания','preventing the rotation of vertebral screws':'предотвращения ротации позвонковых винтов','preventing the Rotation':'предотвращения ротации','preventing the rotation':'предотвращения ротации'})
Q.update({'fixed angle':'с фиксированным углом','variable angle':'с переменным углом','wedge':'клиновидный','with ball tip':'с шаровидным наконечником','T-shape':'Т-образный','parallel':'параллельный','cemented':'для цементной фиксации','quadrangle':'четырёхгранный','cylinder shape':'цилиндрический','round shape':'круглый','interno':'внутренняя','externo':'наружная','spherical':'шаровидная','convex':'выпуклый','with straight handle':'с прямой рукояткой','reversed':'обратная','N.m':'Н·м'})
# Resolve dependent phrases without losing numeric annotations or Roman types.
_original_stem=stem
def stem(text,context):
 if text in BASE:return BASE[text]
 if 'Case' in text:
  # Preserve the exact source family/type; a set context must not turn III into II.
  cases={'Anterior Cervical Plate III Implant Case':'Контейнер имплантов передней шейной пластины III','Anterior Cervical Spine System III Instrument Case':'Контейнер инструментов передней шейной системы III','Anterior Cervical Plate IV Implant Case':'Контейнер имплантов передней шейной пластины IV','Anterior Cervical Plate IV Instrument Case':'Контейнер инструментов передней шейной пластины IV','Delta Cervical Plate and Cage Implants Case':'Контейнер имплантов шейной пластины и кейджа DELTA','Delta Plate and Cage System Instrument Case':'Контейнер инструментов шейной пластины и кейджа DELTA','Laminoplasty Fixation System III Screw Case':'Контейнер винтов для ламинопластики III','Laminoplasty Fixation System II Plate Case':'Контейнер пластин для ламинопластики II','Laminoplasty Fixation System II Instrument Case':'Контейнер инструментов для ламинопластики II','Thoracic-Lumbar Cage (Type M) Instrument Case':'Контейнер инструментов грудопоясничного кейджа типа M'}
  if text in cases:return cases[text]
 if ' for 'in text:
  a,b=text.split(' for ',1)
  if b in DEP:return stem(a,context)+' для '+DEP[b]
 return _original_stem(text,context)

BASE.update({'Holder':'Держатель','Hooding Set':'Держатель','Template':'Шаблон','Cutter Set':'Набор для обрезки'})
_raw_translate=translate
def translate(en,context):
 result=_raw_translate(en,context)
 first=result['ru'].split(',')[0]
 # Adjectives in source qualifiers agree with the instrument name in Russian.
 feminine=any(w in first.lower()for w in ['рукоятка','кюретка','фреза','втулка','отвёртка','спица','трубка','лопатка','воронка','вилка'])
 neuter=any(w in first.lower()for w in ['сверло','шило'])
 plural=any(w in first.lower()for w in ['щипцы','кусачки'])
 endings={'прямой':('прямая','прямое','прямые'),'изогнутый':('изогнутая','изогнутое','изогнутые'),'угловой':('угловая','угловое','угловые'),'левый':('левая','левое','левые'),'правый':('правая','правое','правые'),'канюлированный':('канюлированная','канюлированное','канюлированные'),'малый':('малая','малое','малые'),'большой':('большая','большое','большие'),'короткий':('короткая','короткое','короткие'),'длинный':('длинная','длинное','длинные'),'разборный':('разборная','разборное','разборные'),'неразборный':('неразборная','неразборное','неразборные'),'зелёный':('зелёная','зелёное','зелёные'),'синий':('синяя','синее','синие'),'красный':('красная','красное','красные'),'жёлтый':('жёлтая','жёлтое','жёлтые'),'четырёхгранный':('четырёхгранная','четырёхгранное','четырёхгранные')}
 if feminine or neuter or plural:
  index=0 if feminine else 1 if neuter else 2
  head,*suffix=result['ru'].split(',')
  text=','.join(suffix)
  for a,v in endings.items():text=re.sub(r'\b'+a+r'\b',v[index],text)
  result['ru']=head+(','+text if suffix else'')
 return result
